// Generated by scripts/sync-examples.ts from scripts/example-app. Do not edit.
// Runs the platform SDK cases (Lucent modules calling UIKit / android.os).
import { useEffect, useState } from "react";
import { Pressable, ScrollView, Text, View } from "react-native";
import { sdkCases } from "../sdk/cases";
import type { SdkCase } from "../sdk/types";
import { styles } from "./styles";

type SdkResult = { name: string; pass: boolean; got: string; expected: string; ms: number };

async function runSdkCase(c: SdkCase): Promise<SdkResult> {
  const start = Date.now();
  let got: string;
  try {
    got = await c.run();
  } catch (e) {
    got = e instanceof Error ? `${e.name}: ${e.message}` : String(e);
  }
  const pass = typeof c.expected === "string" ? got === c.expected : c.expected.test(got);
  return { name: c.name, pass, got, expected: String(c.expected), ms: Date.now() - start };
}

export function SdkScreen() {
  const [results, setResults] = useState<SdkResult[]>([]);
  const [running, setRunning] = useState(false);

  async function runAll() {
    setRunning(true);
    setResults([]);
    const out: SdkResult[] = [];
    for (const c of sdkCases) {
      out.push(await runSdkCase(c));
      setResults([...out]);
    }
    setRunning(false);
  }

  useEffect(() => {
    void runAll();
  }, []);

  const passed = results.filter((r) => r.pass).length;
  const done = !running && results.length === sdkCases.length;

  return (
    <>
      <View style={styles.header}>
        <Text style={styles.title}>Lucent · platform SDKs</Text>
        <Text style={styles.subtitle}>
          {results.length}/{sdkCases.length} run · {passed} passed
        </Text>
        <Text testID="lucent-sdk-summary" style={[styles.summary, done && (passed === sdkCases.length ? styles.ok : styles.bad)]}>
          {running ? "Running…" : done ? (passed === sdkCases.length ? "ALL PASSED" : `${sdkCases.length - passed} FAILED`) : ""}
        </Text>
        <Pressable disabled={running} onPress={runAll} style={({ pressed }) => [styles.button, (pressed || running) && styles.pressed]}>
          <Text style={styles.buttonText}>Run again</Text>
        </Pressable>
      </View>
      <ScrollView contentContainerStyle={styles.list}>
        {results.map((r) => (
          <View key={r.name} style={styles.row}>
            <Text style={styles.rowTitle}>
              {r.pass ? "✅" : "❌"} {r.name} <Text style={styles.ms}>{r.ms} ms</Text>
            </Text>
            <Text style={[styles.line, !r.pass && styles.lineBad]}>{r.pass ? r.got : `expected: ${r.expected}\n     got: ${r.got}`}</Text>
          </View>
        ))}
      </ScrollView>
    </>
  );
}
